-- M4 immutable-content/current-eligibility read seam, locale fallback and bounded enumeration.
CREATE FUNCTION gcms_m4.variant_view(t text,k text,r text,l text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d gcms_m4.variant%ROWTYPE;p gcms_m4.publication%ROWTYPE;legacy record;content jsonb;BEGIN
 PERFORM gcms_s05.authorize(t,true);SELECT * INTO d FROM gcms_m4.variant WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;
 IF d.resource_id IS NOT NULL THEN SELECT * INTO p FROM gcms_m4.publication WHERE tenant_id=t AND id=d.active_publication_id;RETURN jsonb_build_object('id',r,'tenantId',t,'kind',k,'locale',l,'version',d.version,'publicationVersion',d.publication_version,'publicationRevision',d.publication_revision,'publishedVersion',p.draft_version,'activePublication',d.active_publication_id IS NOT NULL,'publicationId',d.active_publication_id,'slugLocked',true,'updatedAt',d.updated_at,'content',d.content,'legacy',false);END IF;
 IF k='config' THEN SELECT * INTO legacy FROM gcms_s02.site_draft WHERE tenant_id=t;IF legacy.tenant_id IS NULL THEN RETURN NULL;END IF;
 content:=jsonb_build_object('name',legacy.name,'logo',NULL,'theme','clarity','themeVersion',1,'palette','teal','font','system','layout','comfortable','footer',jsonb_build_object('intro',CASE WHEN l='vi' THEN legacy.footer_intro ELSE '' END,'body',CASE WHEN l='vi' THEN legacy.footer_body ELSE gcms_s02.plain_document('') END),'menu','[]'::jsonb);
 ELSIF k='service' THEN SELECT * INTO legacy FROM gcms_s02.service_draft WHERE tenant_id=t AND id=r;IF legacy.id IS NULL THEN RETURN NULL;END IF;content:=gcms_s08.service_content(legacy)||jsonb_build_object('contentLinks',jsonb_build_object('references',coalesce((SELECT refs FROM gcms_m3.service_links_draft WHERE tenant_id=t AND service_id=r),'[]')));
 ELSIF gcms_m3.kind(k) THEN SELECT * INTO legacy FROM gcms_m3.resource WHERE tenant_id=t AND id=r AND kind=k;IF legacy.id IS NULL THEN RETURN NULL;END IF;content:=legacy.content;
 ELSE RETURN NULL;END IF;
 RETURN jsonb_build_object('id',r,'tenantId',t,'kind',k,'locale',l,'version',CASE WHEN k='config' THEN 0 ELSE legacy.version END,'publicationVersion',0,'publicationRevision',0,'publishedVersion',NULL,'activePublication',false,'publicationId',NULL,'slugLocked',true,'updatedAt',clock_timestamp(),'content',content,'legacy',true);
END $$;
CREATE FUNCTION gcms_m4.reference_eligible(t text,ref jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT CASE WHEN ref->'legacy'='true'::jsonb THEN gcms_m3.reference_eligible(t,ref-ARRAY['locale','legacy','required']) ELSE EXISTS(SELECT 1 FROM gcms_m4.variant d JOIN gcms_m4.publication p ON p.tenant_id=d.tenant_id AND p.kind=d.kind AND p.resource_id=d.resource_id AND p.locale=d.locale WHERE d.tenant_id=t AND d.kind=ref->>'kind' AND d.resource_id=ref->>'id' AND d.locale=ref->>'locale' AND d.active_publication_id IS NOT NULL AND p.id=ref->>'publicationId' AND p.generation=d.generation AND d.generation=(ref->>'generation')::integer AND gcms_m4.text_allowed(t,p.kind,p.resource_id,p.locale,p.draft_version)) END
$$;
CREATE FUNCTION gcms_m4.media(t text,k text,r text,l text,pub text,v integer,a jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('assetId',d.asset_id,'revision',d.revision,'alt',a->>'alt','width',d.width,'height',d.height,'profile','cover','path','/api/public/builder-media/'||t||'/'||k||'/'||r||'/'||l||'/'||pub||'/'||d.asset_id||'/'||d.revision||'/cover') FROM gcms_s07.derivative d WHERE d.tenant_id=t AND d.asset_id=a->>'assetId' AND d.revision=(a->>'revision')::integer AND d.ready AND d.deleted_at IS NULL AND gcms_m4.asset_allowed(t,k,r,l,v,a) ORDER BY d.fence DESC LIMIT 1
$$;
CREATE FUNCTION gcms_m4.legacy_refs(refs jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE r jsonb;out jsonb:='[]';BEGIN FOR r IN SELECT value FROM jsonb_array_elements(coalesce(refs,'[]')) LOOP out:=out||jsonb_build_array(r||jsonb_build_object('locale','vi','references',gcms_m4.legacy_refs(r->'references')));END LOOP;RETURN out;END $$;
CREATE FUNCTION gcms_m4.legacy_page(t text,k text,r text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE s gcms_s02.site_draft%ROWTYPE;page jsonb;cover jsonb;links jsonb;slug_value text;BEGIN
 SELECT * INTO s FROM gcms_s02.site_draft WHERE tenant_id=t;slug_value:=gcms_m4.identity_slug(t,k,r);IF slug_value IS NULL THEN RETURN NULL;END IF;
 IF k='service' THEN page:=gcms_s02.read_public_service(s.slug,slug_value);IF page IS NULL THEN RETURN NULL;END IF;cover:=gcms_s08.read_public_service_cover(s.slug,slug_value);links:=gcms_m3.public_service_links(s.slug,slug_value);
  page:=page||jsonb_build_object('id',r,'kind',k,'content',page->'service','references',gcms_m4.legacy_refs(links->'references'),'media',CASE WHEN cover IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('slot','image','media',cover)) END);
 ELSIF gcms_m3.kind(k) THEN page:=gcms_m3.public_projection(t,r,(SELECT active_publication_id FROM gcms_m3.resource WHERE tenant_id=t AND id=r AND kind=k));IF page IS NULL THEN RETURN NULL;END IF;page:=page||jsonb_build_object('references',gcms_m4.legacy_refs(page->'references'));
 ELSE RETURN NULL;END IF;
 RETURN (page-'service')||jsonb_build_object('schemaVersion',4,'locale','vi','requestedLocale','vi','actualLocale','vi','configPublicationId',NULL,'config',NULL,'sections','[]'::jsonb,'form',NULL,'promotionState',NULL,'alternates','[]'::jsonb,'legacy',true);
END $$;
CREATE FUNCTION gcms_m4.project(t text,k text,r text,l text,pub text DEFAULT NULL,depth integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d gcms_m4.variant%ROWTYPE;p gcms_m4.publication%ROWTYPE;s gcms_s02.site_draft%ROWTYPE;doc jsonb;ref jsonb;child jsonb;refs jsonb:='[]';a jsonb;block jsonb;media_list jsonb:='[]';sections jsonb:='[]';section jsonb;section_refs jsonb;promotion jsonb;form jsonb;action jsonb;resolved_target jsonb;pairs jsonb:='[]';pair jsonb;before_media jsonb;after_media jsonb;idx integer:=0;BEGIN
 IF depth>3 OR NOT gcms_m4.locale(l) OR k='config' THEN RETURN NULL;END IF;
 SELECT site.* INTO s FROM gcms_s02.site_draft site JOIN gcms_s02.tenant ten ON ten.id=site.tenant_id WHERE site.tenant_id=t AND site.public_enabled AND site.slug_locked AND ten.status='active';IF s.tenant_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO d FROM gcms_m4.variant WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;
 IF d.resource_id IS NULL OR d.publication_version=0 THEN IF l='vi' THEN RETURN gcms_m4.legacy_page(t,k,r);ELSE RETURN NULL;END IF;END IF;
 IF d.active_publication_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO p FROM gcms_m4.publication WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l AND id=coalesce(pub,d.active_publication_id) AND generation=d.generation;IF p.id IS NULL OR NOT gcms_m4.text_allowed(t,k,r,l,p.draft_version) THEN RETURN NULL;END IF;doc:=p.content;
 FOR ref IN SELECT value FROM jsonb_array_elements(p.reference_pins) LOOP child:=NULL;
  IF gcms_m4.reference_eligible(t,ref) THEN
   IF ref->'legacy'='true'::jsonb THEN
    IF ref->>'kind'='service' THEN SELECT jsonb_build_object('id',snap.service_id,'kind','service','locale','vi','publicationId',snap.id,'publicationVersion',snap.publication_version,'title',snap.closure->'service'->'title','slug',snap.closure->'service'->'slug','path',gcms_m4.path(s.slug,'vi','service',snap.closure->'service'->>'slug'),'content',snap.closure->'service','references','[]'::jsonb,'media','[]'::jsonb) INTO child FROM gcms_s02.publication_snapshot snap WHERE snap.tenant_id=t AND snap.service_id=ref->>'id' AND snap.id=ref->>'publicationId';
    ELSE child:=gcms_m3.public_projection(t,ref->>'id',ref->>'publicationId',depth+1);IF child IS NOT NULL THEN child:=jsonb_build_object('id',child->'id','kind',child->'kind','locale','vi','publicationId',child->'publicationId','publicationVersion',child->'publicationVersion','title',child->'content'->'title','slug',child->'content'->'slug','path',gcms_m4.path(s.slug,'vi',child->>'kind',child->'content'->>'slug'),'content',child->'content','references',gcms_m4.legacy_refs(child->'references'),'media',child->'media');END IF;END IF;
   ELSE child:=gcms_m4.project(t,ref->>'kind',ref->>'id',l,ref->>'publicationId',depth+1);IF child IS NOT NULL THEN child:=jsonb_build_object('id',child->'id','kind',child->'kind','locale',l,'publicationId',child->'publicationId','publicationVersion',child->'publicationVersion','title',child->'content'->'title','slug',child->'content'->'slug','path',gcms_m4.path(s.slug,l,child->>'kind',child->'content'->>'slug'),'content',child->'content','references',child->'references','media',child->'media');END IF;END IF;
  END IF;
  IF child IS NULL AND ref->'required'='true'::jsonb THEN RETURN NULL;END IF;IF child IS NOT NULL THEN refs:=refs||jsonb_build_array(child);END IF;
 END LOOP;
 FOR a IN SELECT * FROM gcms_m4.assets(k,doc) LOOP block:=gcms_m4.media(t,k,r,l,p.id,p.draft_version,a);IF block IS NOT NULL THEN media_list:=media_list||jsonb_build_array(jsonb_build_object('slot',a->>'usage','media',block));END IF;END LOOP;
 IF k='service' AND doc ? 'coverImage' THEN IF NOT gcms_m4.asset_allowed(t,k,r,l,p.draft_version,(doc->'coverImage')||'{"usage":"page"}') THEN doc:=jsonb_set(doc,'{coverImage}','null');END IF;END IF;
 IF gcms_m3.kind(k) THEN
  IF doc ? 'image' AND doc->'image'<>'null'::jsonb AND NOT gcms_m4.asset_allowed(t,k,r,l,p.draft_version,(doc->'image')||'{"usage":"page"}') THEN doc:=jsonb_set(doc,'{image}','null');END IF;
  IF k='gallery' THEN FOR pair IN SELECT value FROM jsonb_array_elements(doc->'pairs') LOOP IF gcms_m4.asset_allowed(t,k,r,l,p.draft_version,(pair->'before')||'{"usage":"page"}') AND gcms_m4.asset_allowed(t,k,r,l,p.draft_version,(pair->'after')||'{"usage":"page"}') THEN pairs:=pairs||jsonb_build_array(pair);END IF;END LOOP;doc:=jsonb_set(doc,'{pairs}',pairs);END IF;
  doc:=jsonb_set(doc,'{references}',coalesce((SELECT jsonb_agg(jsonb_build_object('kind',x->'kind','id',x->'id','publicationId',x->'publicationId')) FROM jsonb_array_elements(refs) x),'[]'));
 END IF;
 IF k IN ('home','page','landing') THEN FOR section IN SELECT value FROM jsonb_array_elements(doc->'sections') LOOP
  IF section->'hidden'='true'::jsonb THEN CONTINUE;END IF;section_refs:='[]';promotion:=NULL;form:=NULL;action:=NULL;block:=NULL;
  IF section ? 'references' THEN SELECT coalesce(jsonb_agg(x),'[]') INTO section_refs FROM jsonb_array_elements(refs) x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(section->'references') y WHERE y->>'id'=x->>'id' AND y->>'publicationId'=x->>'publicationId');END IF;
  IF section->>'type'='hero' THEN
   IF section->'image'<>'null'::jsonb THEN block:=gcms_m4.media(t,k,r,l,p.id,p.draft_version,(section->'image')||'{"usage":"hero"}');IF block IS NULL THEN section:=jsonb_set(section,'{image}','null');END IF;END IF;
   IF depth<3 AND section->'action'<>'null'::jsonb THEN resolved_target:=gcms_m4.target_path(t,section->'action'->'target',(section->'action'->>'allowViFallback')::boolean);IF resolved_target IS NOT NULL THEN action:=resolved_target||jsonb_build_object('label',section->'action'->>'label');END IF;END IF;
  END IF;
  IF section->>'type'='promotion' THEN promotion:=gcms_m4.project(t,'promotion',section->'reference'->>'id',l,section->'reference'->>'publicationId',depth+1);END IF;
  IF section->>'type'='consultation' THEN
   IF section->'promotion'<>'null'::jsonb THEN promotion:=gcms_m4.project(t,'promotion',section->'promotion'->>'id',l,section->'promotion'->>'publicationId',depth+1);END IF;
   IF section->'promotion'='null'::jsonb OR promotion->>'promotionState'='active' THEN form:=jsonb_build_object('sourceType','landing','sourceId',r,'sourcePublicationId',p.id,'sourceConfigPublicationId',NULL,'formLocale',l,'consent',gcms_m4.consent(l),'promotionId',promotion->'id','promotionPublicationId',promotion->'publicationId','serviceOptions',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(refs) x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(section->'serviceOptions') y WHERE y->>'id'=x->>'id' AND y->>'publicationId'=x->>'publicationId')),'[]'),'locationOptions',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(refs) x WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(section->'locationOptions') y WHERE y->>'id'=x->>'id' AND y->>'publicationId'=x->>'publicationId')),'[]'));END IF;
  END IF;
  sections:=sections||jsonb_build_array(jsonb_build_object('section',section,'action',action,'references',section_refs,'media',block,'promotion',promotion,'form',form));
 END LOOP;doc:=jsonb_set(doc,'{sections}',coalesce((SELECT jsonb_agg(x->'section') FROM jsonb_array_elements(sections) x),'[]'));END IF;
 IF k='service' THEN form:=jsonb_build_object('sourceType','service','sourceId',r,'sourcePublicationId',p.id,'sourceConfigPublicationId',NULL,'formLocale',l,'consent',gcms_m4.consent(l),'promotionId',NULL,'promotionPublicationId',NULL,'serviceOptions','[]'::jsonb,'locationOptions',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(refs) x WHERE x->>'kind'='location'),'[]'));ELSE form:=NULL;END IF;
 RETURN jsonb_build_object('schemaVersion',4,'id',r,'kind',k,'locale',l,'requestedLocale',l,'actualLocale',l,'publicationId',p.id,'publicationVersion',p.publication_version,'publishedAt',p.published_at,'canonicalUrl',s.canonical_origin||gcms_m4.path(s.slug,l,k,doc->>'slug'),'configPublicationId',NULL,'config',NULL,'site',p.site,'content',doc,'references',refs,'media',media_list,'sections',sections,'form',form,'promotionState',CASE WHEN k<>'promotion' THEN NULL WHEN statement_timestamp()<(doc->>'startAt')::timestamptz THEN 'upcoming' WHEN statement_timestamp()>=(doc->>'endAt')::timestamptz THEN 'expired' ELSE 'active' END,'alternates','[]'::jsonb,'legacy',false);
END $$;
CREATE FUNCTION gcms_m4.consent(l text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE l WHEN 'vi' THEN jsonb_build_object('version','consultation-vi-v1','copy','Tôi đồng ý để phòng khám sử dụng thông tin đã cung cấp để liên hệ tư vấn theo yêu cầu này.') WHEN 'en' THEN jsonb_build_object('version','consultation-en-v1','copy','I agree that the clinic may use the information I provided to contact me about this consultation request.') END $$;
CREATE FUNCTION gcms_m4.target_path(t text,target jsonb,allow_fallback boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE slug text;lang text:=target->>'locale';s text;page jsonb;BEGIN
 IF NOT gcms_m4.target(target) THEN RETURN NULL;END IF;SELECT sd.slug INTO s FROM gcms_s02.site_draft sd WHERE tenant_id=t;slug:=gcms_m4.identity_slug(t,target->>'kind',target->>'id');IF slug IS NULL THEN RETURN NULL;END IF;
 page:=gcms_m4.project(t,target->>'kind',target->>'id',lang,NULL,3);IF page IS NULL AND lang='en' AND allow_fallback THEN lang:='vi';page:=gcms_m4.project(t,target->>'kind',target->>'id','vi',NULL,3);END IF;IF page IS NULL THEN RETURN NULL;END IF;RETURN jsonb_build_object('path',gcms_m4.path(s,lang,target->>'kind',slug),'actualLocale',lang,'fallback',lang IS DISTINCT FROM target->>'locale');
END $$;
CREATE FUNCTION gcms_m4.config(t text,l text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d gcms_m4.variant%ROWTYPE;p gcms_m4.publication%ROWTYPE;menu jsonb:='[]';i jsonb;target jsonb;logo jsonb;doc jsonb;BEGIN
 IF NOT EXISTS(SELECT 1 FROM gcms_s02.site_draft sd JOIN gcms_s02.tenant ten ON ten.id=sd.tenant_id WHERE sd.tenant_id=t AND sd.public_enabled AND sd.slug_locked AND ten.status='active') THEN RETURN NULL;END IF;SELECT * INTO d FROM gcms_m4.variant WHERE tenant_id=t AND kind='config' AND resource_id=t AND locale=l;IF d.active_publication_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO p FROM gcms_m4.publication WHERE tenant_id=t AND id=d.active_publication_id;doc:=p.content;
 FOR i IN SELECT value FROM jsonb_array_elements(doc->'menu') LOOP target:=gcms_m4.target_path(t,i->'target',(i->>'allowViFallback')::boolean);IF target IS NOT NULL THEN menu:=menu||jsonb_build_array(i||target);END IF;END LOOP;
 IF doc->'logo'<>'null'::jsonb THEN logo:=gcms_m4.media(t,'config',t,l,p.id,p.draft_version,(doc->'logo')||'{"usage":"logo"}');IF logo IS NULL THEN doc:=jsonb_set(doc,'{logo}','null');END IF;END IF;
 RETURN jsonb_build_object('publicationId',p.id,'publicationVersion',p.publication_version,'locale',l,'content',doc,'menu',menu,'logoMedia',logo);
END $$;
CREATE FUNCTION gcms_m4.decorate(t text,l text,page jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE config jsonb;sections jsonb:='[]';s jsonb;other jsonb;alternates jsonb:='[]';k text:=page->>'kind';r text:=page->>'id';BEGIN
 IF page IS NULL THEN RETURN NULL;END IF;config:=gcms_m4.config(t,l);
 IF l='en' AND config IS NULL THEN RETURN NULL;END IF;
 IF config IS NOT NULL THEN page:=page||jsonb_build_object('config',config,'configPublicationId',config->'publicationId','site',jsonb_build_object('name',config->'content'->'name','footer',config->'content'->'footer'));END IF;
 IF page->'form'<>'null'::jsonb THEN page:=jsonb_set(page,'{form,sourceConfigPublicationId}',coalesce(config->'publicationId','null'));END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(page->'sections') LOOP IF s->'form'<>'null'::jsonb THEN s:=jsonb_set(s,'{form,sourceConfigPublicationId}',coalesce(config->'publicationId','null'));END IF;sections:=sections||jsonb_build_array(s);END LOOP;page:=jsonb_set(page,'{sections}',sections);
 FOR s IN SELECT to_jsonb(x) FROM unnest(ARRAY['vi','en']) x LOOP other:=gcms_m4.project(t,k,r,s#>>'{}');IF other IS NOT NULL AND ((s#>>'{}')='vi' OR gcms_m4.config(t,'en') IS NOT NULL) THEN alternates:=alternates||jsonb_build_array(jsonb_build_object('locale',s,'url',other->'canonicalUrl','publicationId',other->'publicationId'));END IF;END LOOP;
 page:=jsonb_set(page,'{alternates}',alternates);IF octet_length(page::text)>1048576 OR gcms_m3.graph_nodes(page->'references')>250 THEN RETURN NULL;END IF;RETURN page;
END $$;
CREATE FUNCTION gcms_m4.read_public(tenant_slug text,l text,k text,slug_value text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t text;r text;page jsonb;fallback jsonb;BEGIN
 IF NOT gcms_m4.locale(l) OR NOT gcms_m4.kind(k) OR k='config' THEN RETURN NULL;END IF;SELECT tenant_id INTO t FROM gcms_s02.site_draft WHERE slug=tenant_slug;
 r:=CASE WHEN k='service' THEN (SELECT id FROM gcms_s02.service_draft WHERE tenant_id=t AND slug=slug_value) WHEN gcms_m3.kind(k) THEN (SELECT id FROM gcms_m3.resource WHERE tenant_id=t AND kind=k AND slug=slug_value) ELSE (SELECT id FROM gcms_m4.identity WHERE tenant_id=t AND kind=k AND slug=slug_value) END;IF r IS NULL THEN RETURN NULL;END IF;
 page:=gcms_m4.decorate(t,l,gcms_m4.project(t,k,r,l));IF page IS NOT NULL THEN RETURN jsonb_build_object('resolution','page','requestedLocale',l,'actualLocale',l,'canonicalUrl',page->'canonicalUrl','fallbackPublicationId',NULL,'page',page);END IF;
 IF l='en' THEN fallback:=gcms_m4.decorate(t,'vi',gcms_m4.project(t,k,r,'vi'));IF fallback IS NOT NULL THEN RETURN jsonb_build_object('resolution','fallback','requestedLocale','en','actualLocale','vi','canonicalUrl',fallback->'canonicalUrl','fallbackPublicationId',fallback->'publicationId','page',NULL);END IF;END IF;RETURN NULL;
END $$;
CREATE FUNCTION gcms_m4.public_candidates(t text,k text) RETURNS TABLE(id text,slug text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT d.id,d.slug FROM gcms_s02.service_draft d WHERE d.tenant_id=t AND k='service' UNION ALL SELECT d.id,d.slug FROM gcms_m3.resource d WHERE d.tenant_id=t AND d.kind=k UNION ALL SELECT d.id,d.slug FROM gcms_m4.identity d WHERE d.tenant_id=t AND d.kind=k $$;
CREATE FUNCTION gcms_m4.public_list(tenant_slug text,l text,k text,q text,after_id text,lim integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t text;row record;page jsonb;items jsonb:='[]';candidate jsonb;BEGIN
 IF lim NOT BETWEEN 1 AND 51 OR length(q)>160 OR NOT gcms_m4.locale(l) OR NOT gcms_m4.kind(k) OR k='config' THEN RETURN NULL;END IF;SELECT s.tenant_id INTO t FROM gcms_s02.site_draft s JOIN gcms_s02.tenant ten ON ten.id=s.tenant_id WHERE s.slug=tenant_slug AND s.public_enabled AND s.slug_locked AND ten.status='active';IF t IS NULL THEN RETURN NULL;END IF;
 FOR row IN SELECT * FROM gcms_m4.public_candidates(t,k) c WHERE (after_id IS NULL OR c.id>after_id) ORDER BY c.id LOOP
  page:=gcms_m4.decorate(t,l,gcms_m4.project(t,k,row.id,l));IF page IS NULL OR (q<>'' AND position(q IN lower(page->'content'->>'title'))=0 AND position(q IN row.slug)=0) THEN CONTINUE;END IF;
  candidate:=jsonb_build_object('id',row.id,'kind',k,'locale',l,'publicationId',page->'publicationId','publicationVersion',page->'publicationVersion','title',page->'content'->'title','slug',row.slug,'content',page->'content');IF octet_length((items||jsonb_build_array(candidate))::text)>900000 THEN EXIT;END IF;items:=items||jsonb_build_array(candidate);IF jsonb_array_length(items)>=lim THEN EXIT;END IF;
 END LOOP;RETURN jsonb_build_object('schemaVersion',4,'locale',l,'kind',k,'items',items,'config',gcms_m4.config(t,l),'canonicalUrl','http://localhost:5892/'||tenant_slug||CASE WHEN l='en' THEN '/en' ELSE '' END||CASE WHEN k IN ('home','page') THEN '' WHEN k='landing' THEN '/landing' WHEN k='promotion' THEN '/khuyen-mai' ELSE '/'||gcms_m3.path(k) END);
END $$;
CREATE FUNCTION gcms_m4.media_target(t text,k text,r text,l text,pub text,a text,v integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE page jsonb;config jsonb;BEGIN
 IF k='config' THEN config:=gcms_m4.config(t,l);IF config->>'publicationId' IS DISTINCT FROM pub OR config->'logoMedia'->>'assetId' IS DISTINCT FROM a OR config->'logoMedia'->>'revision' IS DISTINCT FROM v::text THEN RETURN NULL;END IF;
 ELSE page:=gcms_m4.project(t,k,r,l,pub);IF page IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(page->'media') x WHERE x->'media'->>'assetId'=a AND x->'media'->>'revision'=v::text) THEN RETURN NULL;END IF;END IF;
 RETURN (SELECT jsonb_build_object('key',object_key,'bytes',bytes) FROM gcms_s07.derivative WHERE tenant_id=t AND asset_id=a AND revision=v AND ready AND deleted_at IS NULL ORDER BY fence DESC LIMIT 1);
END $$;
-- Admission runs after immutable row creation inside the same transaction; failure rolls the command back.
CREATE FUNCTION gcms_m4.admission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE page jsonb;BEGIN IF NEW.kind<>'config' THEN page:=gcms_m4.project(NEW.tenant_id,NEW.kind,NEW.resource_id,NEW.locale,NEW.active_publication_id);IF page IS NULL OR octet_length(page::text)>1048576 OR gcms_m3.graph_nodes(page->'references')>250 THEN RAISE EXCEPTION 'Publication eligibility or graph admission failed' USING ERRCODE='23514';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER public_admission AFTER UPDATE OF active_publication_id ON gcms_m4.variant FOR EACH ROW WHEN(NEW.active_publication_id IS NOT NULL AND NEW.active_publication_id IS DISTINCT FROM OLD.active_publication_id) EXECUTE FUNCTION gcms_m4.admission();

CREATE FUNCTION gcms_m4.legacy_state(t text,k text,r text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT CASE WHEN k='service' THEN (SELECT jsonb_build_object('version',d.version,'publicationRevision',coalesce(h.revision,0),'pointer',h.active_snapshot_id,'generation',coalesce((SELECT generation FROM gcms_m3.service_generation WHERE tenant_id=t AND service_id=r),0)) FROM gcms_s02.service_draft d LEFT JOIN gcms_s08.publication_head h ON h.tenant_id=d.tenant_id AND h.service_id=d.id WHERE d.tenant_id=t AND d.id=r) WHEN gcms_m3.kind(k) THEN (SELECT jsonb_build_object('version',version,'publicationRevision',publication_revision,'pointer',active_publication_id,'generation',generation) FROM gcms_m3.resource WHERE tenant_id=t AND id=r AND kind=k) END $$;
CREATE FUNCTION gcms_m4.guard_legacy_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE tenant_key text;resource_key text;kind_value text;BEGIN
 IF TG_TABLE_NAME='service_draft' THEN tenant_key:=NEW.tenant_id;resource_key:=NEW.id;kind_value:='service';ELSIF TG_TABLE_NAME='publication_snapshot' THEN tenant_key:=NEW.tenant_id;resource_key:=NEW.service_id;kind_value:='service';ELSIF TG_TABLE_NAME='publication_pointer' THEN tenant_key:=coalesce(NEW.tenant_id,OLD.tenant_id);resource_key:=coalesce(NEW.service_id,OLD.service_id);kind_value:='service';ELSE tenant_key:=NEW.tenant_id;resource_key:=NEW.id;kind_value:=NEW.kind;END IF;
 IF EXISTS(SELECT 1 FROM gcms_m4.variant WHERE tenant_id=tenant_key AND kind=kind_value AND resource_id=resource_key AND locale='vi' AND publication_version>0) THEN RAISE EXCEPTION 'M4_ADOPTED: use site-builder locale editor' USING ERRCODE='23514';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$;
CREATE TRIGGER m4_service_write_guard BEFORE UPDATE ON gcms_s02.service_draft FOR EACH ROW EXECUTE FUNCTION gcms_m4.guard_legacy_write();
CREATE TRIGGER m4_service_publish_guard BEFORE INSERT ON gcms_s02.publication_snapshot FOR EACH ROW EXECUTE FUNCTION gcms_m4.guard_legacy_write();
CREATE TRIGGER m4_service_pointer_guard BEFORE INSERT OR UPDATE OR DELETE ON gcms_s02.publication_pointer FOR EACH ROW EXECUTE FUNCTION gcms_m4.guard_legacy_write();
CREATE TRIGGER m4_content_write_guard BEFORE UPDATE ON gcms_m3.resource FOR EACH ROW EXECUTE FUNCTION gcms_m4.guard_legacy_write();


CREATE FUNCTION gcms_m4.preview_issues(t text,k text,r text,l text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d jsonb;a jsonb;issues jsonb:='[]';BEGIN
 PERFORM gcms_s05.authorize(t,true);d:=gcms_m4.variant_view(t,k,r,l);IF d IS NULL THEN RETURN '["RESOURCE_UNAVAILABLE"]';END IF;
 BEGIN PERFORM gcms_m4.pin_refs(t,k,r,l,d->'content');EXCEPTION WHEN check_violation THEN issues:=issues||'"REFERENCE_UNAVAILABLE"'::jsonb;END;
 IF k IN ('case','gallery','testimonial') AND NOT gcms_m4.text_allowed(t,k,r,l,(d->>'version')::integer) THEN issues:=issues||'"TEXT_PERMISSION_REQUIRED"'::jsonb;END IF;
 FOR a IN SELECT * FROM gcms_m4.assets(k,d->'content') LOOP IF NOT gcms_m4.asset_allowed(t,k,r,l,(d->>'version')::integer,a) THEN issues:=issues||'"MEDIA_PERMISSION_OR_READINESS"'::jsonb;END IF;END LOOP;RETURN issues;
END $$;
CREATE FUNCTION gcms_m4.public_config(tenant_slug text,l text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT gcms_m4.config(tenant_id,l) FROM gcms_s02.site_draft WHERE slug=tenant_slug $$;
CREATE FUNCTION gcms_m4.reference_options(t text,k text,l text,q text,after_id text,lim integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE row record;page jsonb;out jsonb:='[]';BEGIN
 PERFORM gcms_s05.authorize(t,true);IF lim NOT BETWEEN 1 AND 51 OR length(q)>160 OR NOT gcms_m4.kind(k) OR NOT gcms_m4.locale(l) THEN RAISE EXCEPTION 'Invalid options' USING ERRCODE='23514';END IF;
 FOR row IN SELECT * FROM gcms_m4.public_candidates(t,k) c WHERE after_id IS NULL OR c.id>after_id ORDER BY c.id LOOP page:=gcms_m4.project(t,k,row.id,l);IF page IS NULL OR (q<>'' AND position(q IN lower(page->'content'->>'title'))=0 AND position(q IN row.slug)=0) THEN CONTINUE;END IF;out:=out||jsonb_build_array(jsonb_build_object('id',row.id,'kind',k,'locale',l,'publicationId',page->'publicationId','publicationVersion',page->'publicationVersion','title',page->'content'->'title','slug',row.slug,'content',page->'content'));IF jsonb_array_length(out)>=lim THEN EXIT;END IF;END LOOP;RETURN out;
END $$;
CREATE FUNCTION gcms_m4.seo(tenant_slug text,after_key text,lim integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t text;row record;page jsonb;out jsonb:='[]';BEGIN
 IF lim NOT BETWEEN 1 AND 51 THEN RETURN NULL;END IF;SELECT s.tenant_id INTO t FROM gcms_s02.site_draft s JOIN gcms_s02.tenant ten ON ten.id=s.tenant_id WHERE s.slug=tenant_slug AND s.public_enabled AND s.slug_locked AND ten.status='active';IF t IS NULL THEN RETURN NULL;END IF;
 FOR row IN SELECT c.*,lang AS locale FROM (SELECT 'service'::text AS kind,id FROM gcms_s02.service_draft WHERE tenant_id=t UNION ALL SELECT kind,id FROM gcms_m3.resource WHERE tenant_id=t UNION ALL SELECT kind,id FROM gcms_m4.identity WHERE tenant_id=t) c CROSS JOIN unnest(ARRAY['vi','en']) lang WHERE after_key IS NULL OR c.kind||':'||c.id||':'||lang>after_key ORDER BY c.kind,c.id,lang LOOP
 page:=gcms_m4.decorate(t,row.locale,gcms_m4.project(t,row.kind,row.id,row.locale));IF page IS NULL THEN CONTINUE;END IF;out:=out||jsonb_build_array(jsonb_build_object('id',row.id,'kind',row.kind,'locale',row.locale,'path',substring(page->>'canonicalUrl' FROM length('http://localhost:5892')+1),'canonicalUrl',page->'canonicalUrl','publicationId',page->'publicationId','configPublicationId',page->'configPublicationId','alternates',page->'alternates'));IF jsonb_array_length(out)>=lim THEN EXIT;END IF;END LOOP;RETURN out;
END $$;

REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA gcms_m4 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gcms_m4.variant_view(text,text,text,text),gcms_m4.command(text,text,text,text,jsonb),gcms_m4.read_public(text,text,text,text),gcms_m4.public_list(text,text,text,text,text,integer),gcms_m4.config(text,text),gcms_m4.media_target(text,text,text,text,text,text,integer) TO gcms_s02_tenant;

GRANT EXECUTE ON FUNCTION gcms_m4.preview_issues(text,text,text,text),gcms_m4.public_config(text,text),gcms_m4.reference_options(text,text,text,text,text,integer),gcms_m4.seo(text,text,integer) TO gcms_s02_tenant;
